'use strict';
const C=TripCore, $=(s,root=document)=>root.querySelector(s), $$=(s,root=document)=>[...root.querySelectorAll(s)];
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const paths={home:'M3 10 12 3l9 7v10a1 1 0 0 1-1 1h-5v-7H9v7H4a1 1 0 0 1-1-1Z',wallet:'M20 8V5a2 2 0 0 0-2-2H5a3 3 0 0 0 0 6h16v11H5a3 3 0 0 1-3-3V6m19 7h-5v4h5',plane:'m22 2-7 20-4-9-9-4 20-7ZM11 13 22 2',folder:'M3 5h6l2 3h10v12H3Z',user:'M16 7a4 4 0 1 1-8 0 4 4 0 0 1 8 0ZM4 21v-2a8 8 0 0 1 16 0v2',plus:'M12 5v14M5 12h14',arrow:'M5 12h14m-5-5 5 5-5 5',chevron:'m9 5 7 7-7 7',down:'m6 9 6 6 6-6',bell:'M18 8a6 6 0 0 0-12 0c0 7-3 7-3 9h18c0-2-3-2-3-9M10 21h4',moon:'M20 15A9 9 0 0 1 9 3a9 9 0 1 0 11 12Z',sun:'M16 12a4 4 0 1 1-8 0 4 4 0 0 1 8 0ZM12 1v2m0 18v2M1 12h2m18 0h2M4 4l2 2m12 12 2 2M4 20l2-2M18 6l2-2',calendar:'M4 5h16v16H4ZM4 10h16M8 2v6m8-6v6',check:'m5 12 4 4L19 6',close:'m6 6 12 12M6 18 18 6',search:'M17 10a7 7 0 1 1-14 0 7 7 0 0 1 14 0Zm-2 5 6 6',download:'M12 3v12m-5-5 5 5 5-5M4 16v5h16v-5',upload:'M12 16V4m-5 5 5-5 5 5M4 17v4h16v-4',logout:'M9 4H3v16h6m5-13 5 5-5 5m-5-5h13',edit:'m16 3 5 5-12 12-6 1 1-6L16 3Zm-3 3 5 5',trash:'M3 6h18M9 6V3h6v3M5 6l1 15h12l1-15M10 10v7m4-7v7',food:'M5 3v7m4-7v7M3 3v5a4 4 0 0 0 8 0V3M7 12v9M20 3c-5 3-5 9 0 9V3Zm0 9v9',stay:'M3 20V5m18 15V9H3m0 8h18M7 9V5h6v4',car:'m4 9 2-5h12l2 5M3 9h18v9H3ZM6 18v3m12-3v3M6 13h2m8 0h2',spark:'m12 2 3 7 7 3-7 3-3 7-3-7-7-3 7-3Z',bag:'M4 7h16l1 14H3L4 7Zm4 0V5a4 4 0 0 1 8 0v2',more:'M5 12h.01M12 12h.01M19 12h.01',lock:'M6 10h12v11H6Zm3 0V6a3 3 0 0 1 6 0v4',globe:'M21 12a9 9 0 1 1-18 0 9 9 0 0 1 18 0ZM3 12h18M12 3c5 5 5 13 0 18-5-5-5-13 0-18Z',refresh:'M20 7a9 9 0 1 0 1 9M20 2v6h-6',file:'M5 2h9l5 5v15H5Zm9 0v6h5M8 12h8m-8 4h6',link:'m10 14 4-4M8 16l-2 2a4 4 0 0 1-5-5l5-5a4 4 0 0 1 5 0m2 0 2-2a4 4 0 0 1 6 6l-5 5a4 4 0 0 1-5 0',pin:'M19 9c0 5-7 12-7 12S5 14 5 9a7 7 0 1 1 14 0Zm-5 0a2 2 0 1 1-4 0 2 2 0 0 1 4 0',shield:'m12 2 9 4v6c0 5-9 10-9 10S3 17 3 12V6l9-4Z',clock:'M21 12a9 9 0 1 1-18 0 9 9 0 0 1 18 0Zm-9-6v6l4 2'};
const icon=(name,cls='')=>`<svg class="icon ${cls}" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="${paths[name]||paths.file}"/></svg>`;
let data=null,page='home',expenseTab='all',vaultTab='all',selectedUser='sujay',busy=false;
let filters={search:'',category:'',member:'',from:'',to:'',status:''};
const names=Object.fromEntries(C.MEMBERS.map(u=>[u.id,u.name]));
const color=id=>['sage','peach','lavender','sand','blue'][C.MEMBERS.findIndex(u=>u.id===id)]||'sage';
const avatar=(id,size='')=>`<span class="avatar ${color(id)} ${size}" title="${esc(names[id])}">${esc(names[id]?.[0]||'?')}</span>`;
const money=(minor,currency='INR')=>new Intl.NumberFormat('en-IN',{style:'currency',currency,maximumFractionDigits:minor%100===0 && currency==='INR'?0:C.CURRENCIES[currency],minimumFractionDigits:minor%100===0 && currency==='INR'?0:C.CURRENCIES[currency]}).format(minor/10**C.CURRENCIES[currency]);
const amountValue=(n,c='INR')=>(n/10**C.CURRENCIES[c]).toFixed(C.CURRENCIES[c]);
const today=()=>{const d=new Date();return `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`;};
const dateLabel=(s,opts={day:'numeric',month:'short'})=>s?new Date(s.slice(0,10)+'T12:00:00').toLocaleDateString('en-GB',opts):'Dates to come';
const categoryIcon=c=>({'Food & drinks':'food',Stay:'stay',Transport:'car',Experiences:'spark',Shopping:'bag',Other:'more'}[c]||'file');
const btn=(label,action,extra='',cls='button')=>`<button class="${cls}" data-action="${action}" ${extra}>${label}</button>`;
const empty=(title,copy,action,label,ico='folder')=>`<div class="empty"><span class="empty-icon">${icon(ico)}</span><h3>${title}</h3><p>${copy}</p>${action?btn(icon('plus')+label,action,'','button secondary'):''}</div>`;
function toast(message,error=false){const el=document.createElement('div');el.className='toast'+(error?' error':'');el.textContent=message;$('#toasts').append(el);setTimeout(()=>el.remove(),6500);}
function showModal(title,content,wide=false){cancelImageScan();const dialog=$('#modal');dialog.innerHTML=`<header class="modal-head"><div><span class="eyebrow">VIETNAM, TOGETHER</span><h2 id="modal-title">${title}</h2></div>${btn(icon('close'),'close','aria-label="Close dialog"','icon-button')}</header>${content}`;dialog.classList.toggle('wide',wide);if(!dialog.open)dialog.showModal();dialog.scrollTop=0;}
function closeModal(){if(!busy)cancelImageScan();if(!busy)$('#modal').close();}
function formError(message){const box=$('.form-error',$('#modal'));if($('#modal').open && box){box.textContent=message;box.hidden=false;box.scrollIntoView({block:'nearest'});}else toast(message,true);}
function footer(label='Save changes'){return `<div class="form-error" role="alert" hidden></div><footer class="form-footer">${btn('Cancel','close','','button ghost')}<button class="button" type="submit">${icon('check')}${label}</button></footer>`;}
function field(label,name,value='',type='text',extra=''){return `<label class="field"><span>${label}</span><input type="${type}" name="${name}" value="${esc(value)}" ${extra}></label>`;}
function select(label,name,options,value='',extra=''){return `<label class="field"><span>${label}</span><select name="${name}" ${extra}>${options.map(o=>{const v=typeof o==='string'?o:o.value,l=typeof o==='string'?o:o.label;return `<option value="${esc(v)}" ${v===value?'selected':''}>${esc(l)}</option>`;}).join('')}</select></label>`;}
function membersInput(name,selected,label){return `<fieldset class="member-field"><legend>${label}</legend><div class="member-pills">${C.MEMBERS.map(u=>`<label class="member-pill"><input type="checkbox" name="${name}" value="${u.id}" ${selected.includes(u.id)?'checked':''}>${avatar(u.id,'tiny')}<span>${u.name}</span></label>`).join('')}</div></fieldset>`;}
const notes=(value='',label='Notes')=>`<label class="field"><span>${label}</span><textarea name="notes" rows="3" maxlength="2000" placeholder="Anything the group should know…">${esc(value)}</textarea></label>`;
function welcome(){data=null;resetAdminReport();$('#app').innerHTML=`<main class="welcome"><section class="welcome-photo"><a class="brand light" href="./"><img src="assets/mark.svg" alt=""><span>together<span class="brand-dot">.</span></span></a><div class="welcome-story"><span class="eyebrow light-text">OUR NEXT ADVENTURE</span><h1>A little further.<br>A lot closer.</h1><p>The places we’ll discover.<br>The moments we’ll share.</p><span class="location-tag">${icon('pin')} Ha Long Bay, Vietnam</span></div><div class="photo-caption">GOOD COMPANY. GREAT MEMORIES.</div></section><section class="welcome-content"><div class="welcome-top">A shared journey, beautifully organized.${btn(icon(document.documentElement.dataset.theme==='dark'?'sun':'moon'),'theme','aria-label="Toggle color theme"','icon-button')}</div><div class="welcome-inner"><span class="eyebrow">ONE TRIP. FIVE TRAVELERS.</span><h2>Vietnam, together<span>.</span></h2><p class="intro">Every little adventure.<br>Every expense accounted for.</p><div class="choose-heading"><h3>Choose your account</h3><span>01 — 05</span></div><div class="account-list">${C.MEMBERS.map(u=>`<button class="account-button" data-action="login" data-id="${u.id}">${avatar(u.id)}<span><strong>${u.name}</strong><small>Personal account</small></span>${icon('arrow')}</button>`).join('')}</div><p class="privacy-note">${icon('lock')} Your own account. A shared adventure.<br><span>Your password or private access code is required to sign in.</span></p>${TRIP_CONFIG.allowPreview?btn('Take a look around '+icon('arrow'),'preview','','preview-link')+'<p class="preview-caption">Explore a sample trip · No sign-in needed</p>':''}</div><div class="welcome-bottom"><span>MADE FOR THE FIVE OF US</span><span>Hanoi · Ha Long · Hoi An</span></div></section></main>`;}
function loginModal(id){selectedUser=id;showModal(`Welcome, ${esc(names[id])}.`,`<form id="login-form" autocomplete="on"><input type="hidden" name="username" autocomplete="username" value="${esc(id)}"><p class="muted">Enter your password, or use the original private access code if you have not changed it.</p>${field('Password or access code','code','','password','required autocomplete="current-password" maxlength="128" autofocus')}<p class="hint">Your code is checked by the trip backend. Choosing a name alone never opens an account.</p>${!TRIP_CONFIG.appsScriptUrl?'<div class="notice">Google Sheets is not connected yet. Follow README.md to deploy the backend, or explore the sample trip from the welcome screen.</div>':''}${footer('Sign in '+icon('arrow'))}</form>`);}
function nav(mobile=false){const items=['home','itinerary','map','expenses','flights','files',...(data.me.role==='admin'?['admin']:[]),'profile'];return items.map(n=>`<button class="nav-item ${page===n?'active':''}" data-page="${n}" ${page===n?'aria-current="page"':''}>${icon({home:'home',itinerary:'calendar',map:'globe',expenses:'wallet',flights:'plane',files:'folder',admin:'shield',profile:'user'}[n])}<span>${(mobile?{home:'Home',itinerary:'Itinerary',map:'Map',expenses:'Expenses',flights:'Flights',files:'Files',admin:'Admin',profile:'Profile'}:{home:'Overview',itinerary:'Itinerary',map:'Map',expenses:'Expenses',flights:'Flights',files:'Shared vault',admin:'Admin dashboard',profile:'My account'})[n]}</span>${page===n?'<i></i>':''}</button>`).join('');}
function render(){if(!data)return welcome();const preview=TripAPI.mode==='preview';$('#app').innerHTML=`<div class="app-shell"><aside class="sidebar"><a class="brand" href="./"><img src="assets/mark.svg" alt=""><span>together<span class="brand-dot">.</span></span></a><div class="trip-switch"><span class="trip-emblem">✦</span><div><strong>Vietnam trip</strong><small>Our next chapter</small></div>${icon('down')}</div><span class="nav-label">YOUR TRIP</span><nav aria-label="Main navigation">${nav()}</nav><div class="sidebar-bottom"><div class="sidebar-note">${icon('globe')}<span>Less keeping tabs.<br>More making memories.</span></div><button class="sidebar-user" data-page="profile">${avatar(data.me.id)}<span><strong>${esc(data.me.name)}</strong><small>${preview?'Sample account':'Personal account'}</small></span>${icon('chevron')}</button></div></aside><div class="main-shell"><header class="topbar"><div class="breadcrumb">Our adventures ${icon('chevron')} <span>${esc(data.settings.name)}</span></div><div class="top-actions">${preview?'<span class="preview-badge"><span></span>Sample trip</span>':'<span class="connected-badge"><span></span>Private trip</span>'}${btn(icon('refresh'),'refresh','aria-label="Refresh trip" title="Refresh trip"','icon-button refresh-button')}${btn(icon(document.documentElement.dataset.theme==='dark'?'sun':'moon'),'theme','aria-label="Toggle color theme"','icon-button')}${btn(icon('bell')+'<i class="notification-dot"></i>','notifications','aria-label="Trip activity"','icon-button notification-button')}${avatar(data.me.id,'small')}</div></header><main class="main-content" id="main-content">${page==='home'?homeView():page==='itinerary'?itineraryView():page==='map'?mapView():page==='expenses'?expensesView():page==='flights'?flightsView():page==='files'?filesView():page==='admin'?adminView():profileView()}</main><footer class="app-footer"><span>A little planning. A lot of living.</span><span>${preview?'Sample data stays in this browser':'Last synced '+new Date(data.syncedAt).toLocaleTimeString('en-IN',{hour:'2-digit',minute:'2-digit'})} · INR ₹</span></footer></div><nav class="mobile-nav ${data.me.role==='admin'?'admin-navigation':''}" aria-label="Mobile navigation">${nav(true)}</nav></div>`;if(page==='itinerary')requestAnimationFrame(alignSelectedDay);if(page==='home')requestAnimationFrame(alignHomeDay);if(page==='map')requestAnimationFrame(()=>{alignMapDay();if(mapCityOpen)initCityVisitMap();});}
function heading(eyebrow,title,subtitle,actions=''){return `<div class="page-heading"><div><span class="eyebrow">${eyebrow}</span><h1>${title}</h1><p>${subtitle}</p></div><div class="heading-actions">${actions}</div></div>`;}
const balances=()=>C.balances(data.expenses,data.splits,data.settlements);
function expenseRows(expenses){return expenses.map(e=>`<button class="expense-row" data-action="expense-detail" data-id="${esc(e.id)}"><span class="category-icon ${color(e.payerId)}">${icon(categoryIcon(e.category))}</span><span class="expense-title"><strong>${esc(e.title)}</strong><small>${esc(e.category)}<span>·</span>${dateLabel(e.date)}</small></span><span class="expense-payer">${avatar(e.payerId,'tiny')}<span>${esc(names[e.payerId])} paid</span></span><span class="expense-amount"><strong>${money(e.baseMinor)}</strong><small>${e.currency!=='INR'?money(e.originalMinor,e.currency):'Split with '+data.splits.filter(s=>s.expenseId===e.id).length+' travelers'}</small></span>${icon('chevron')}</button>`).join('');}

function categorySummary(){const colors=['#668574','#d4ae7b','#7f9cad','#b3a3c3','#d28b72','#a0aaa4'];return C.CATEGORIES.map((name,i)=>({name,color:colors[i],amount:data.expenses.filter(e=>e.category===name).reduce((s,e)=>s+e.baseMinor,0)})).filter(c=>c.amount).sort((a,b)=>b.amount-a.amount);}
function filteredExpenses(){return data.expenses.filter(e=>(!filters.search || (e.title+' '+e.notes).toLowerCase().includes(filters.search.toLowerCase()))&&(!filters.category || e.category===filters.category)&&(!filters.member || e.payerId===filters.member || data.splits.some(s=>s.expenseId===e.id && s.userId===filters.member))&&(!filters.from || e.date>=filters.from)&&(!filters.to || e.date<=filters.to)).sort((a,b)=>b.date.localeCompare(a.date));}
function expensesView(){const list=filteredExpenses(),total=list.reduce((s,e)=>s+e.baseMinor,0);return heading('EVERY LITTLE THING, ACCOUNTED FOR','Shared experiences. Fair splits.','Keep the memories. We’ll keep the numbers.',btn(icon('download')+'Export CSV','export','','button secondary')+btn(icon('plus')+'Add expense','add-expense'))+`<div class="section-tabs">${['all','settlements','summary'].map(t=>btn({all:'All expenses',settlements:'Settle up',summary:'Spending summary'}[t],'expense-tab',`data-id="${t}"`,expenseTab===t?'tab active':'tab')).join('')}<span>${data.expenses.length} expenses</span></div>`+personalPaymentCard()+(expenseTab==='settlements'?settlementsView():expenseTab==='summary'?summaryView():`<div class="filter-bar"><label class="search-field">${icon('search')}<input id="expense-search" aria-label="Search expenses" placeholder="Find an expense…" value="${esc(filters.search)}"></label>${select('Category','filter-category',[{value:'',label:'All categories'},...C.CATEGORIES],filters.category)}${select('Traveler','filter-member',[{value:'',label:'All travelers'},...C.MEMBERS.map(u=>({value:u.id,label:u.name}))],filters.member)}${field('From','filter-from',filters.from,'date')}${field('To','filter-to',filters.to,'date')}</div><section class="panel"><div class="panel-heading"><h2>Expense history</h2><span class="muted">${list.length} expenses · ${money(total)}</span></div>${list.length?`<div class="expense-list">${expenseRows(list)}</div>`:empty('Nothing here just yet','Try a different filter, or add a shared expense.','add-expense','Add expense','wallet')}</section>`);}
function settlementsView(){const b=balances(),plan=C.settlementPlan(b);return `<div class="settlement-intro"><div><h2>A clear way to settle up.</h2><p>Suggested transfers simplify the group’s net balances. A repayment counts after the recipient confirms it.</p></div><div class="row-actions">${btn(icon('plus')+'Record money received','received-settlement','','button secondary')}${btn('Record payment sent','add-settlement','','button secondary')}</div></div><div class="balance-grid">${C.MEMBERS.map(u=>`<article class="mini-balance">${avatar(u.id)}<div><strong>${u.name}</strong><span class="${b[u.id].net<0?'debit':'credit'}">${b[u.id].net===0?'All settled':money(Math.abs(b[u.id].net))+(b[u.id].net>0?' to receive':' to pay')}</span></div></article>`).join('')}</div><section class="panel"><div class="panel-heading"><h2>Suggested repayments</h2><span class="subtle">${icon('spark')} Fewer transfers, same fair result</span></div>${plan.length?plan.map(p=>`<div class="settlement-row"><div class="transfer-people">${avatar(p.fromId,'small')}<strong>${names[p.fromId]}</strong>${icon('arrow')}${avatar(p.toId,'small')}<strong>${names[p.toId]}</strong></div><strong>${money(p.amountMinor)}</strong>${p.fromId===data.me.id?btn('Record payment','add-settlement',`data-to="${p.toId}" data-amount="${p.amountMinor}"`,'button small secondary'):p.toId===data.me.id?btn('Record received','received-settlement',`data-from="${p.fromId}" data-amount="${p.amountMinor}"`,'button small secondary'):'<span class="muted">Awaiting sender</span>'}</div>`).join(''):empty('All square.','Everyone’s confirmed balance is settled.','','','check')}</section><section class="panel spaced"><div class="panel-heading"><h2>Repayment history</h2>${select('Status','filter-status',[{value:'',label:'All statuses'},'pending','confirmed','cancelled'],filters.status)}</div>${data.settlements.filter(s=>!filters.status||s.status===filters.status).map(s=>`<div class="settlement-row"><div><strong>${names[s.fromId]} ${icon('arrow')} ${names[s.toId]}</strong><small>${dateLabel(s.date)} · ${esc(s.notes||'Repayment')}</small></div><strong>${money(s.amountMinor)}</strong><span class="status ${s.status}">${s.status}</span><div class="row-actions">${s.status==='pending'&&s.toId===data.me.id?btn('Confirm receipt','confirm-settlement',`data-id="${s.id}"`,'button small'):''}${s.status==='pending'&&[s.fromId,s.toId].includes(data.me.id)?btn('Cancel','cancel-settlement',`data-id="${s.id}"`,'button ghost small'):''}</div></div>`).join('')||'<p class="empty-inline">No repayments to show.</p>'}</section>`;}
function summaryView(){const total=data.expenses.reduce((s,e)=>s+e.baseMinor,0),b=balances();return `<div class="summary-grid"><section class="panel"><div class="panel-heading"><h2>Where the memories went</h2><strong>${money(total)}</strong></div><div class="spending-bars">${categorySummary().map(c=>`<div class="spending-category"><div><span><i style="background:${c.color}"></i>${esc(c.name)}</span><strong>${money(c.amount)} <small>${Math.round(c.amount/total*100)}%</small></strong></div><div class="bar-track"><span style="width:${c.amount/total*100}%;background:${c.color}"></span></div></div>`).join('')||'<p class="muted">Add an expense to see a breakdown.</p>'}</div></section><section class="panel"><div class="panel-heading"><h2>Each traveler’s share</h2></div><div class="table-scroll"><table><thead><tr><th>Traveler</th><th>Paid</th><th>Share</th><th>Net balance</th></tr></thead><tbody>${C.MEMBERS.map(u=>`<tr><td>${avatar(u.id,'tiny')}${u.name}</td><td>${money(b[u.id].paid)}</td><td>${money(b[u.id].share)}</td><td>${b[u.id].net<0?'−':'+'}${money(Math.abs(b[u.id].net))}</td></tr>`).join('')}</tbody></table></div><p class="hint panel-padding">Positive balances are owed to the traveler. Confirmed repayments are included.</p></section></div>`;}
function flightsView(){const flights=[...data.flights].sort((a,b)=>Date.parse(a.departureAt+a.departureZone)-Date.parse(b.departureAt+b.departureZone));return heading('THE WAY THERE. AND EVERYWHERE.','Your journey, in one place.','Flight times are local to each airport. Only flights shared with you appear here.',btn(icon('plus')+'Add flight','add-flight'))+`<section class="flights-layout">${flights.length?flights.map(f=>`<article class="panel flight-card"><div class="flight-card-top"><span class="airline-logo">${icon('plane')}</span><div><strong>${esc(f.airline)}</strong><small>${esc(f.number)} · ${dateLabel(f.departureAt,{day:'numeric',month:'long',year:'numeric'})}</small></div><span class="status">${f.sharedWith.length===5?'Whole crew':'Selected travelers'}</span></div><div class="flight-route"><div><h2>${esc(f.departure)}</h2><strong>${esc(f.departureAt.slice(11))}</strong><small>UTC${esc(f.departureZone)}</small></div><div class="flight-line"><span></span>${icon('plane')}<span></span></div><div><h2>${esc(f.arrival)}</h2><strong>${esc(f.arrivalAt.slice(11))}</strong><small>${dateLabel(f.arrivalAt)} · UTC${esc(f.arrivalZone)}</small></div></div><div class="flight-card-bottom"><div class="stacked-avatars">${f.passengers.map(id=>avatar(id,'small')).join('')}</div><span>${f.passengers.length} ${f.passengers.length===1?'passenger':'passengers'}</span>${btn('Flight details '+icon('arrow'),'flight-detail',`data-id="${f.id}"`,'text-button')}</div>${flightBookingActions(f)}${f.reminder?`<p class="flight-reminder">${icon('bell')}${esc(f.reminder)}</p>`:''}</article>`).join(''):empty('The journey starts here.','Add your first flight, then keep times, tickets and travel details together.','add-flight','Add a flight','plane')}</section><div class="info-strip">${icon('clock')} Add departure and arrival time zones so your itinerary stays in the right order.</div>`;}
function filesView(){const docs=data.documents.filter(d=>![PLAN_CATEGORY,HOTEL_CATEGORY].includes(d.category)).filter(d=>vaultTab==='all'||(vaultTab==='files'?d.kind==='file':vaultTab==='planning'?['note','activity','link','contact'].includes(d.kind):d.kind==='checklist'));return heading('THE THINGS WE’LL NEED ALONG THE WAY','A little home for all the details.','Bookings, receipts, plans, and the things you don’t want to forget.',btn(icon('plus')+'Add to vault','add-document'))+`<div class="section-tabs">${[['all','Everything'],['files','Documents'],['planning','Plans & places'],['checklist','Packing list']].map(([id,label])=>btn(label,'vault-tab',`data-id="${id}"`,vaultTab===id?'tab active':'tab')).join('')}<span>${data.documents.length} items</span></div><div class="vault-grid">${docs.length?docs.map(d=>`<article class="panel vault-card"><div class="vault-card-top"><span class="category-icon ${d.kind==='checklist'?'sage':d.kind==='activity'?'peach':'sand'}">${icon({file:'file',note:'edit',checklist:'check',activity:'pin',link:'link',contact:'user'}[d.kind])}</span><span class="vault-type">${esc(d.category)}</span>${d.kind==='checklist'?`<button class="check-button ${d.checked?'checked':''}" data-action="toggle-checklist" data-id="${d.id}" aria-label="${d.checked?'Mark incomplete':'Mark complete'}: ${esc(d.title)}" aria-pressed="${!!d.checked}">${d.checked?icon('check'):''}</button>`:icon(d.sharedWith.length===5?'user':'lock')}</div><button class="vault-card-body" data-action="document-detail" data-id="${d.id}"><h3 class="${d.checked?'completed':''}">${esc(d.title)}</h3><p>${esc(d.notes||d.filename||'All the details, safely in one place.')}</p></button><div class="vault-card-footer">${avatar(d.ownerId,'tiny')}<span>${esc(names[d.ownerId])}${d.date?' · '+dateLabel(d.date):''}</span><small>${d.sharedWith.length===5?'Everyone':d.sharedWith.filter(id=>id!==d.ownerId).length?'Selected travelers':'Only you'}</small></div></article>`).join(''):empty('Make a little room for the details.','Keep travel documents, packing lists, and your next great idea together.','add-document','Add to vault','folder')}</div>`;}
function profileView(){const b=balances()[data.me.id];return heading('YOUR OWN CORNER OF THE ADVENTURE','Hey, '+esc(data.me.name)+'.','Your account, preferences, and personal spending at a glance.')+`<div class="profile-grid"><section class="panel profile-card">${avatar(data.me.id,'large')}<h2>${esc(data.me.name)}</h2><p>${data.me.role==='admin'?'Admin · Trip organizer':'Fellow adventurer'} · ${TripAPI.mode==='preview'?'Sample account':'Private account'}</p><div class="profile-stats"><div><span>You’ve paid</span><strong>${money(b.paid)}</strong></div><div><span>Your share</span><strong>${money(b.share)}</strong></div><div><span>${b.net>=0?'You’re owed':'You owe'}</span><strong>${money(Math.abs(b.net))}</strong></div></div>${data.me.role==='admin'?'<button class="button full-width admin-profile-entry" data-page="admin">'+icon('shield')+'Admin dashboard'+icon('arrow')+'</button>':''}${btn(icon('logout')+'Sign out','logout','','button secondary full-width')}</section><div><section class="panel"><div class="panel-heading"><h2>Just the way you like it</h2></div><div class="setting-row"><div><strong>Color theme</strong><p>Follow your mood. Light or dark.</p></div>${btn(icon(document.documentElement.dataset.theme==='dark'?'sun':'moon')+'Switch theme','theme','','button secondary small')}</div><div class="setting-row"><div><strong>Trip settings</strong><p>Budget, dates and exchange rates.</p></div>${data.me.role==='admin'?btn('Manage '+icon('arrow'),'settings','','text-button'):'<span class="muted">Managed by Sujay</span>'}</div><div class="setting-row"><div><strong>Password</strong><p>Choose your own password after signing in.</p></div>${TripAPI.mode==='live'?btn('Change password','change-password','','button secondary small'):'<span class="muted">Private account only</span>'}</div><div class="setting-row"><div><strong>Your expense history</strong><p>Download expenses involving you.</p></div>${btn(icon('download')+'Export','personal-export','','button secondary small')}</div></section><section class="panel spaced"><div class="panel-heading"><h2>A space you can trust</h2>${icon('shield')}</div><p class="panel-padding muted">${TripAPI.mode==='preview'?'You’re exploring a sample trip. This browser’s preview data is separate from the real trip. Sample account switching is available below.':'Your sign-in is checked by the backend. Private files are visible only to their owner and selected travelers. Shared expenses are visible to the whole crew. Refreshing this page signs you out.'}</p>${TripAPI.mode==='preview'?`<div class="preview-switch">${C.MEMBERS.map(u=>btn(avatar(u.id,'tiny')+u.name,'switch-preview',`data-id="${u.id}"`,'button secondary small')).join('')}${btn('Reset sample trip','reset-preview','','text-button danger')}</div>`:'<p class="hint panel-padding">Forgot your password? Ask the organizer for a replacement access code. A password change signs out all your sessions.</p>'}</section></div></div><section class="panel spaced"><div class="panel-heading"><h2>Your recent expenses</h2></div>${expenseRows(data.expenses.filter(e=>e.payerId===data.me.id || data.splits.some(s=>s.expenseId===e.id && s.userId===data.me.id)).slice(-5).reverse())||'<p class="empty-inline">Your first expense is still ahead.</p>'}</section>`;}
function expenseForm(id){const e=data.expenses.find(e=>e.id===id),ids=e?data.splits.filter(s=>s.expenseId===id).map(s=>s.userId):C.MEMBERS.map(u=>u.id);showModal(e?'Edit the expense':'A little expense. A shared memory.',`<form id="expense-form" data-id="${esc(id||'')}" data-version="${e?.version||''}" data-request-id="${crypto.randomUUID()}">${!e?scanWidget():''}${field('What was it for?','title',e?.title||'','text','required maxlength="100" placeholder="Dinner by the river…"')}<div class="form-grid three">${field('Amount','amount',e?amountValue(e.originalMinor,e.currency):'','text','required inputmode="decimal" placeholder="0.00"')}${select('Currency','currency',Object.keys(C.CURRENCIES),e?.currency||'INR')}${field('1 unit → INR','rate',e?.rate||'1','text','required inputmode="decimal"')}</div><p class="hint rate-hint">This rate is saved with the bill. Future rate changes won’t change this expense.</p><div class="form-grid">${select('Category','category',C.CATEGORIES,e?.category||'Food & drinks')}${field('Date','date',e?.date||today(),'date','required')}${select('Paid by','payerId',C.MEMBERS.map(u=>({value:u.id,label:u.name})),e?.payerId||data.me.id)}${select('Split the bill','splitType',[{value:'equal',label:'Equally'},{value:'custom',label:'Custom amounts'},{value:'percentage',label:'By percentage'}],e?.splitType||'equal')}</div>${membersInput('participants',ids,'Who shared this moment?')}<div id="allocation-fields">${C.MEMBERS.map(u=>field(u.name,`allocation-${u.id}`,e?.allocations?.[u.id]||'','text','inputmode="decimal" placeholder="0" data-user="'+u.id+'"')).join('')}</div><div class="split-preview" id="split-preview" aria-live="polite"></div>${notes(e?.notes)}${!e?'<label class="file-drop">'+icon('upload')+'<strong>Add a receipt <span>(optional)</span></strong><small>PDF, PNG, JPEG, WebP, TXT or CSV · Up to 5 MB</small><input name="receipt" type="file" accept=".pdf,.png,.jpg,.jpeg,.webp,.txt,.csv"></label>':''}${footer(e?'Save expense':'Add expense')}</form>`,true);updateSplitPreview();}
function expensePayload(form){const f=new FormData(form),p=Object.fromEntries(f.entries());p.participants=f.getAll('participants');p.allocations=Object.fromEntries(C.MEMBERS.map(u=>[u.id,f.get('allocation-'+u.id)||'0']));delete p.receipt;delete p.scanImage;C.MEMBERS.forEach(u=>delete p['allocation-'+u.id]);if(form.dataset.id){p.id=form.dataset.id;p.version=Number(form.dataset.version);}return p;}
function updateSplitPreview(){const form=$('#expense-form');if(!form)return;const p=expensePayload(form);$('#allocation-fields').hidden=p.splitType==='equal';$$('#allocation-fields .field').forEach(label=>{label.hidden=!p.participants.includes($('input',label).dataset.user);});try{const e=C.expense({...p,title:p.title||'Preview',date:p.date||today()});$('#split-preview').innerHTML=`<div><strong>${money(e.baseMinor)} total</strong><span>${p.splitType==='equal'?'Split equally':'Custom split'} · ${p.participants.length} travelers</span></div><div class="split-chips">${e.splits.map(s=>`<span>${names[s.userId]} <strong>${money(s.amountMinor)}</strong></span>`).join('')}</div>`;}catch(error){$('#split-preview').textContent=p.amount?error.message:'Add an amount to see everyone’s share.';}}
function expenseDetail(id){const e=data.expenses.find(e=>e.id===id);if(!e)return;const canEdit=e.ownerId===data.me.id||data.me.role==='admin';const docs=data.documents.filter(d=>d.expenseId===id);showModal(esc(e.title),`<div class="detail-amount">${money(e.baseMinor)}<small>${money(e.originalMinor,e.currency)} · 1 ${e.currency} = ₹${esc(e.rate)}</small></div><div class="detail-meta"><span>${icon(categoryIcon(e.category))}${esc(e.category)}</span><span>${icon('calendar')}${dateLabel(e.date,{day:'numeric',month:'long',year:'numeric'})}</span></div><div class="paid-by">${avatar(e.payerId,'small')}<span>Paid by <strong>${names[e.payerId]}</strong></span></div><h3 class="detail-label">Everyone’s share</h3><div class="share-list">${data.splits.filter(s=>s.expenseId===id).map(s=>`<div>${avatar(s.userId,'tiny')}<span>${names[s.userId]}</span><strong>${money(s.amountMinor)}</strong></div>`).join('')}</div>${e.notes?`<p class="detail-note">${esc(e.notes)}</p>`:''}<div class="detail-label-row"><h3>Receipts & attachments</h3>${btn(icon('plus')+'Attach','attach-expense',`data-id="${e.id}"`,'text-button')}</div>${docs.map(d=>btn(icon('file')+esc(d.title)+icon('download'),'download',`data-id="${d.id}"`,'attachment')).join('')||'<p class="muted">No receipts shared with you yet.</p>'}<p class="hint">Created ${dateLabel(e.createdAt)} · Updated ${dateLabel(e.updatedAt)} · Revision ${e.version}</p><div class="detail-actions">${canEdit?btn(icon('trash')+'Delete','delete-expense',`data-id="${e.id}"`,'button ghost danger')+btn(icon('edit')+'Edit expense','edit-expense',`data-id="${e.id}"`,'button secondary'):''}${btn('Done','close')}</div>`);}
function flightBookingActions(f){const portal=TripBookingLinks.portal(f);return portal?`<div class="flight-booking-actions">${externalLink(portal.url,'Manage booking · '+portal.name)}${f.pnr?btn('Copy PNR','copy-pnr',`data-id="${esc(f.id)}"`,'button secondary small'):''}</div>`:'';}
function flightForm(id){const f=data.flights.find(x=>x.id===id);showModal(f?'Edit your flight':'The next part of the journey.',`<form id="flight-form" data-id="${id||''}" data-version="${f?.version||''}" data-request-id="${crypto.randomUUID()}">${!f?scanWidget():''}<div class="form-grid">${field('Airline','airline',f?.airline||'','text','required maxlength="80"')}${field('Flight number','number',f?.number||'','text','required maxlength="20"')}${field('Departure airport','departure',f?.departure||'','text','required maxlength="60" placeholder="Airport name or code"')}${field('Arrival airport','arrival',f?.arrival||'','text','required maxlength="60"')}${field('Local departure','departureAt',f?.departureAt||'','datetime-local','required')}${field('Local arrival','arrivalAt',f?.arrivalAt||'','datetime-local','required')}${field('Departure UTC offset','departureZone',f?.departureZone||'+05:30','text','required pattern="(?:[+]|-)(?:(?:0[0-9]|1[0-3]):[0-5][0-9]|14:00)" placeholder="+05:30"')}${field('Arrival UTC offset','arrivalZone',f?.arrivalZone||'+07:00','text','required pattern="(?:[+]|-)(?:(?:0[0-9]|1[0-3]):[0-5][0-9]|14:00)" placeholder="+07:00"')}${field('Booking reference / PNR','pnr',f?.pnr||'','text','maxlength="50"')}${field('Terminal','terminal',f?.terminal||'','text','maxlength="100"')}${field('Baggage allowance','baggage',f?.baggage||'','text','maxlength="200"')}${field('Reminder / ticket details','reminder',f?.reminder||'','text','maxlength="200" placeholder="Check-in opens 48 hours before"')}${field('Booking confirmation link','bookingUrl',f?.bookingUrl||'','url','placeholder="https://…"')}${field('Check-in link','checkinUrl',f?.checkinUrl||'','url','placeholder="https://…"')}</div>${membersInput('passengers',f?.passengers||[data.me.id],'Who’s on this flight?')}${membersInput('sharedWith',f?.sharedWith||C.MEMBERS.map(u=>u.id),'Who can view the booking and PNR?')}<p class="hint">The owner always has access. Uncheck everyone else to keep this booking private.</p>${notes(f?.notes)}${footer('Save flight')}</form>`,true);}
function flightDetail(id){const f=data.flights.find(x=>x.id===id);if(!f)return;const docs=data.documents.filter(d=>d.flightId===id);showModal(`${esc(f.airline)} · ${esc(f.number)}`,`<div class="flight-route detail"><div><h2>${esc(f.departure)}</h2><strong>${esc(f.departureAt.slice(11))}</strong><small>${dateLabel(f.departureAt)} · UTC${esc(f.departureZone)}</small></div><div class="flight-line">${icon('plane')}</div><div><h2>${esc(f.arrival)}</h2><strong>${esc(f.arrivalAt.slice(11))}</strong><small>${dateLabel(f.arrivalAt)} · UTC${esc(f.arrivalZone)}</small></div></div><dl class="detail-list">${[['Booking reference',f.pnr||'Not added'],['Passengers',f.passengers.map(id=>names[id]).join(', ')],['Terminal',f.terminal||'Not added'],['Baggage',f.baggage||'Not added'],['Reminder',f.reminder||'Not added']].map(([a,b])=>`<div><dt>${a}</dt><dd>${esc(b)}</dd></div>`).join('')}</dl>${TripBookingLinks.portal(f)?flightBookingActions(f)+'<p class="flight-booking-help">Open the airline site and enter the booking reference / PNR above and the passenger’s name exactly as on the ticket. The airline may request additional booking details.</p>':''}${f.notes?`<p class="detail-note">${esc(f.notes)}</p>`:''}<div class="detail-links">${f.bookingUrl?externalLink(f.bookingUrl,'Booking confirmation'):''}${f.checkinUrl?externalLink(f.checkinUrl,'Check in'):''}${btn(icon('calendar')+'Calendar reminder','flight-calendar',`data-id="${f.id}"`,'button secondary small')}</div><div class="detail-label-row"><h3>Your tickets</h3>${btn(icon('plus')+'Attach ticket','attach-flight',`data-id="${f.id}"`,'text-button')}</div>${docs.map(d=>btn(icon('file')+esc(d.title)+icon('download'),'download',`data-id="${d.id}"`,'attachment')).join('')||'<p class="muted">No tickets attached yet.</p>'}<div class="detail-actions">${f.ownerId===data.me.id?btn(icon('trash')+'Delete','delete-flight',`data-id="${f.id}"`,'button ghost danger')+btn(icon('edit')+'Edit','edit-flight',`data-id="${f.id}"`,'button secondary'):''}${btn('Done','close')}</div>`);}
function externalLink(url,label){try{C.url(url);return `<a class="button secondary small" href="${esc(url)}" target="_blank" rel="noopener noreferrer">${esc(label)}${icon('arrow')}</a>`;}catch{return '';}}
function documentForm(id,linked={}){const d=data.documents.find(x=>x.id===id);showModal(d?'Edit the little details':'Something worth keeping.',`<form id="document-form" data-id="${id||''}" data-version="${d?.version||''}" data-expense-id="${esc(d?.expenseId||linked.expenseId||'')}" data-flight-id="${esc(d?.flightId||linked.flightId||'')}" data-request-id="${crypto.randomUUID()}">${!d?scanWidget():''}${field('Title','title',d?.title||'','text','required maxlength="100" placeholder="Give it a name…"')}<div class="form-grid">${select('What are you adding?','kind',[{value:'file',label:'Document or receipt'},{value:'checklist',label:'Packing / checklist item'},{value:'activity',label:'Place or activity'},{value:'note',label:'Itinerary note'},{value:'link',label:'Shared link'},{value:'contact',label:'Emergency contact'}],d?.kind||linked.kind||'file',d?'disabled':'')}${select('Category','category',['Travel','Tickets','Hotels','Visa & documents','Receipts','Activities','Insurance','Packing','Places to visit','Emergency','Other'],d?.category||linked.category||'Travel')}</div><label class="file-drop" id="vault-file-field">${icon('upload')}<strong>${d?.filename?esc(d.filename):'Choose a file'}</strong><small>PDF, PNG, JPEG, WebP, TXT or CSV · Up to 5 MB</small>${!d?'<input type="file" name="file" accept=".pdf,.png,.jpg,.jpeg,.webp,.txt,.csv">':''}</label><div class="form-grid">${field('Date (optional)','date',d?.date||'','date')}${field('Link (optional)','url',d?.url||'','url','placeholder="https://…"')}</div>${notes(d?.notes,d?.kind==='contact'?'Contact information':'Notes & details')}${membersInput('sharedWith',d?.sharedWith||linked.sharedWith||C.MEMBERS.map(u=>u.id),'Share with')}<p class="hint">The owner always has access. Uncheck everyone else for a private item.</p>${footer('Save to vault')}</form>`,true);updateFileField();}
function updateFileField(){const form=$('#document-form');if(form)$('#vault-file-field').hidden=form.elements.kind.value!=='file';}
function documentDetail(id){const d=data.documents.find(x=>x.id===id);if(!d)return;showModal(esc(d.title),`<div class="detail-meta"><span>${icon(d.kind==='file'?'file':'folder')}${esc(d.category)}</span><span>${icon('lock')}${d.sharedWith.length===5?'Shared with everyone':d.sharedWith.filter(i=>i!==d.ownerId).map(i=>names[i]).join(', ')||'Only the owner'}</span></div><p class="detail-note">${esc(d.notes||'No additional notes.')}</p>${d.date?`<p>${icon('calendar')}${dateLabel(d.date,{day:'numeric',month:'long',year:'numeric'})}</p>`:''}${d.url?externalLink(d.url,'Open saved link'):''}${d.filename?`<p class="hint">${esc(d.filename)} · ${Math.ceil(d.size/1024)} KB</p>`+btn(icon('download')+'Download file','download',`data-id="${d.id}"`):''}${d.kind==='checklist'?btn(icon('check')+(d.checked?'Mark incomplete':'Mark complete'),'toggle-checklist',`data-id="${d.id}"`,'button secondary'):''}<p class="hint">Added by ${names[d.ownerId]} · ${dateLabel(d.createdAt)}</p><div class="detail-actions">${d.ownerId===data.me.id?btn(icon('trash')+'Delete','delete-document',`data-id="${d.id}"`,'button ghost danger')+btn(icon('edit')+'Edit','edit-document',`data-id="${d.id}"`,'button secondary'):''}${btn('Done','close')}</div>`);}
function settlementForm(to='',amount=''){showModal('A little settling up.',`<form id="settlement-form" data-request-id="${crypto.randomUUID()}"><div class="notice">Record money you have actually sent. The recipient must confirm it before balances change.</div><div class="form-grid">${select('Paid to','toId',C.MEMBERS.filter(u=>u.id!==data.me.id).map(u=>({value:u.id,label:u.name})),to)}${field('Amount (INR)','amount',amount?amountValue(Number(amount)):'','text','required inputmode="decimal"')}${field('Date paid','date',today(),'date','required')}</div>${notes('','Payment reference or note')}${footer('Record repayment')}</form>`);}
function receivedSettlementForm(from='',amount=''){showModal('Record money received',`<form id="received-settlement-form" data-request-id="${crypto.randomUUID()}"><div class="notice">Confirm money ${esc(data.me.name)} actually received. This immediately updates both travelers’ balances. If the sender already recorded this payment, use Confirm receipt in repayment history instead to avoid counting it twice.</div><div class="form-grid">${select('Received from','fromId',C.MEMBERS.filter(u=>u.id!==data.me.id).map(u=>({value:u.id,label:u.name})),from)}${field('Amount received (INR)','amount',amount?amountValue(Number(amount)):'','text','required inputmode="decimal"')}${field('Date received','date',today(),'date','required')}</div>${notes('','Payment reference or note')}${footer('Confirm money received')}</form>`);}
async function passwordForm(){C.assert(TripAPI.mode==='live','Use your private account to change your password.');const auth=await TripAPI.call('authInfo',{userId:data.me.id});showModal('Change your password.',`<form id="password-form" data-request-id="${crypto.randomUUID()}"><p class="notice">${auth.salt?'Enter the password you currently use to sign in.':'For your first change, enter the original 64-character access code as your current password.'}</p><p class="muted">Only your own account will change. Use 12–128 characters. You will be signed out on all devices after saving.</p>${field('Current password or access code','currentPassword','','password','required autocomplete="current-password" maxlength="128"')}${field('New password','newPassword','','password','required autocomplete="new-password" minlength="12" maxlength="128"')}${field('Confirm new password','confirmation','','password','required autocomplete="new-password" minlength="12" maxlength="128"')}${footer('Change password')}</form>`);}
function settingsForm(){const s=data.settings;showModal('A few plans for the adventure.',`<form id="settings-form" data-version="${s.version}" data-request-id="${crypto.randomUUID()}">${field('Trip name','name',s.name,'text','required maxlength="100"')}<div class="form-grid">${field('Trip starts','startDate',s.startDate,'date')}${field('Trip ends','endDate',s.endDate,'date')}${field('Group budget (INR)','budget',amountValue(s.budgetMinor),'text','required inputmode="decimal"')}</div><h3 class="detail-label">Agreed exchange rates</h3><p class="hint">INR per 1 unit of foreign currency. Verify rates before use; these are manually configured, not live rates. Historical bills keep their original rate.</p><div class="form-grid">${Object.keys(C.CURRENCIES).filter(c=>c!=='INR').map(c=>field('1 '+c+' = INR','rate-'+c,s.rates[c]||'','text','required inputmode="decimal"')).join('')}</div>${footer('Save trip settings')}</form>`,true);}
function notifications(){showModal('A few things from the crew.',`<div class="activity-list">${data.notifications.map(n=>`<div>${avatar(n.actorId,'small')}<span><strong>${names[n.actorId]}</strong> ${esc(n.action.toLowerCase())}<small>${dateLabel(n.createdAt)} · ${new Date(n.createdAt).toLocaleTimeString('en-IN',{hour:'2-digit',minute:'2-digit'})}</small></span></div>`).join('')||'<p class="muted">New expenses, shared tickets and trip updates will appear here after refresh.</p>'}</div>`);}
async function readFile(file){if(!file||!file.size)return null;C.assert(file.size<=5*1024*1024,'Files must be 5 MB or smaller.');const ext=file.name.split('.').pop().toLowerCase(),mimeType={pdf:'application/pdf',png:'image/png',jpg:'image/jpeg',jpeg:'image/jpeg',webp:'image/webp',txt:'text/plain',csv:'text/csv'}[ext];C.assert(mimeType,'Supported files: PDF, PNG, JPEG, WebP, TXT and CSV.');const buffer=await file.arrayBuffer(),bytes=new Uint8Array(buffer);let binary='';for(let i=0;i<bytes.length;i+=8192)binary+=String.fromCharCode(...bytes.subarray(i,i+8192));return{base64:btoa(binary),filename:file.name,mimeType};}
function downloadBlob(content,name,type='text/csv;charset=utf-8'){const url=URL.createObjectURL(new Blob([content],{type}));const a=document.createElement('a');a.href=url;a.download=name;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),1000);}
async function downloadFile(id){const file=await TripAPI.call('download',{id});const bytes=Uint8Array.from(atob(file.base64),c=>c.charCodeAt(0));downloadBlob(bytes,file.filename,file.mimeType);toast('Download ready.');}
function exportCSV(personal=false){let list=personal?data.expenses.filter(e=>e.payerId===data.me.id||data.splits.some(s=>s.expenseId===e.id&&s.userId===data.me.id)):filteredExpenses();const rows=[['Expense ID','Date','Title','Category','Payer','Original amount','Currency','Saved INR rate','Total INR',...C.MEMBERS.map(u=>u.name+' share INR'),'Notes'],...list.map(e=>[e.id,e.date,e.title,e.category,names[e.payerId],amountValue(e.originalMinor,e.currency),e.currency,e.rate,amountValue(e.baseMinor),...C.MEMBERS.map(u=>amountValue(data.splits.find(s=>s.expenseId===e.id&&s.userId===u.id)?.amountMinor||0)),e.notes])];downloadBlob('\uFEFF'+C.csv(rows),(personal?data.me.id+'-':'')+'vietnam-expenses.csv');toast('Your expense report is ready.');}
function calendarDownload(id){const f=data.flights.find(x=>x.id===id),dt=s=>new Date(s).toISOString().replace(/[-:]/g,'').replace(/\.\d{3}/,''),safe=s=>String(s).replace(/\\/g,'\\\\').replace(/\r?\n/g,'\\n').replace(/,/g,'\\,').replace(/;/g,'\\;');const ics=['BEGIN:VCALENDAR','VERSION:2.0','PRODID:-//Vietnam Together//Flights//EN','BEGIN:VEVENT','UID:'+f.id+'@vietnam-together','DTSTAMP:'+dt(new Date().toISOString()),'DTSTART:'+dt(f.departureAt+f.departureZone),'DTEND:'+dt(f.arrivalAt+f.arrivalZone),'SUMMARY:'+safe(f.airline+' '+f.number+' · '+f.departure+' to '+f.arrival),'LOCATION:'+safe(f.departure),'DESCRIPTION:'+safe(f.reminder||'Check your airline for current details.'),'BEGIN:VALARM','TRIGGER:-PT3H','ACTION:DISPLAY','DESCRIPTION:Flight reminder','END:VALARM','END:VEVENT','END:VCALENDAR'].join('\r\n');downloadBlob(ics,'flight-'+f.number.replace(/[^a-z0-9]/gi,'')+'.ics','text/calendar');toast('Calendar file ready, with a reminder three hours before departure.');}
async function mutate(action,payload,requestId){const result=await TripAPI.call(action,payload,requestId||crypto.randomUUID());data=result;if(adminReportData&&data.me.role==='admin')adminReportData={...data,adminMembers:adminReportData.adminMembers};return result;}
function confirmAction(title,copy,action,id){showModal(title,`<p class="muted">${copy}</p><div class="form-error" role="alert" hidden></div><div class="detail-actions">${btn('Keep it','close','','button secondary')}${btn('Confirm','confirmed',`data-operation="${action}" data-id="${id}" data-request-id="${crypto.randomUUID()}"`,'button danger-solid')}</div>`);}
async function act(el){const action=el.dataset.action,id=el.dataset.id;if(busy && !['theme'].includes(action))return;
  if(action==='home-day'){homeDate=id;render();return;}
  if(action==='home-open-day'){itineraryDate=id||homeDate;itineraryTab='days';return navigatePage('itinerary');}
  if(action==='home-hotels'){itineraryTab='hotels';hotelDayFilter=id||'';return navigatePage('itinerary');}
  if(action==='home-add-plan'){itineraryDate=id||homeDate;return planForm();}
  if(action==='map-day'){mapDate=id;mapPlace='';render();requestAnimationFrame(alignMapDay);return;}
  if(action==='map-place'){mapPlace=id;mapCityOpen=true;render();requestAnimationFrame(()=>$('.city-map-detail')?.scrollIntoView({behavior:'smooth',block:'start'}));return;}
  if(action==='map-back'){mapCityOpen=false;render();return;}
  if(action==='map-open-day'){itineraryDate=id;itineraryTab='days';return navigatePage('itinerary');}
  if(action==='map-hotels'){hotelDayFilter=id;itineraryTab='hotels';return navigatePage('itinerary');}
  if(action==='itinerary-tab'){itineraryTab=id;hotelDayFilter='';render();return;}
  if(action==='day-hotels'){itineraryTab='hotels';hotelDayFilter=id;render();return;}
  if(action==='all-hotels'){hotelDayFilter='';render();return;}
  if(action==='select-day'){itineraryDate=id;render();requestAnimationFrame(()=>{alignSelectedDay();$('#day-strip [aria-pressed="true"]')?.focus({preventScroll:true});});return;}
  if(action==='use-hotel-link')return applyHotelLink();
  if(action==='hanoi-plan')return hanoiPlanForm(id);
  if(action==='add-plan'||action==='add-hotel'||action==='edit-plan')return planForm(id,action==='add-hotel');
  if(action==='previous-day'||action==='next-day'){const slides=[...tripDates(),ITINERARY_SUMMARY],current=slides.indexOf(itineraryDate),target=current+(action==='next-day'?1:-1);itineraryDate=slides[target]||itineraryDate;render();return;}
  if(action==='close')return closeModal();
  if(action==='theme'){const theme=document.documentElement.dataset.theme==='dark'?'light':'dark';document.documentElement.dataset.theme=theme;localStorage.setItem('vietnam-theme-v2',theme);render();return;}
  if(action==='login')return loginModal(id);
  if(action==='preview'||action==='switch-preview'){resetAdminReport();data=await TripAPI.startPreview(id||'sujay');page='home';render();toast('Sample trip · Changes are saved only in this browser.');return;}
  if(action==='add-expense'||action==='edit-expense')return expenseForm(id);
  if(action==='expense-detail')return expenseDetail(id);
  if(action==='add-flight'||action==='edit-flight')return flightForm(id);
  if(action==='flight-detail')return flightDetail(id);
  if(action==='add-document'||action==='edit-document')return documentForm(id);
  if(action==='document-detail')return documentDetail(id);
  if(action==='attach-expense')return documentForm(null,{expenseId:id,category:'Receipts'});
  if(action==='attach-flight'){const f=data.flights.find(f=>f.id===id);return documentForm(null,{flightId:id,category:'Tickets',sharedWith:[...new Set([f.ownerId,...f.sharedWith])]});}
  if(action==='add-settlement')return settlementForm(el.dataset.to,el.dataset.amount);
  if(action==='received-settlement')return receivedSettlementForm(el.dataset.from,el.dataset.amount);
  if(action==='admin-refresh')return loadAdminReport();
  if(action==='admin-member'){C.assert(data.me.role==='admin','Admin access is required.');adminFilters.member=id;adminFilters.search='';adminFilters.relationship='involved';render();return;}
  if(action==='admin-clear'){adminFilters={...adminFilters,category:'',from:'',to:'',search:'',relationship:'involved'};render();return;}
  if(action==='admin-export-summary'||action==='admin-export-member')return adminExport(action==='admin-export-summary'?'summary':'member');
  if(action==='change-password')return passwordForm();
  if(action==='settings')return settingsForm();
  if(action==='notifications')return notifications();
  if(action==='settlements'){expenseTab='settlements';return navigatePage('expenses');}
  if(action==='expense-tab'){expenseTab=id;render();return;}
  if(action==='vault-tab'){vaultTab=id;render();return;}
  if(action.startsWith('go-'))return navigatePage(action.slice(3));
  if(action==='export'||action==='personal-export')return exportCSV(action==='personal-export');
  if(action==='copy-pnr'){const flight=data.flights.find(f=>f.id===id);C.assert(flight?.pnr,'No booking reference has been added.');try{await navigator.clipboard.writeText(flight.pnr);toast('Booking reference copied.');}catch{showModal('Your booking reference',`<p class="muted">Copy this reference and enter it on the airline booking page.</p><p class="pnr-tools"><code>${esc(flight.pnr)}</code></p><div class="detail-actions">${btn('Done','close')}</div>`);}return;}
  if(action==='flight-calendar')return calendarDownload(id);
  if(action==='delete-expense')return confirmAction('Delete this expense?','This removes the expense from everyone’s balances. The backend retains its audit history.','deleteExpense',id);
  if(action==='delete-flight')return confirmAction('Remove this flight?','The flight will leave the itinerary. Attached tickets remain in the vault.','deleteFlight',id);
  if(action==='delete-document')return confirmAction('Remove this vault item?','The item will no longer be available through the app. The organizer retains the original file for audit and recovery.','deleteDocument',id);
  if(action==='reset-preview')return confirmAction('Start the sample trip over?','This clears sample edits and uploaded preview files in this browser.','resetPreview','sample');
  if(action==='confirm-settlement'||action==='cancel-settlement')return confirmAction(action==='confirm-settlement'?'Have you received the money?':'Cancel this repayment?',action==='confirm-settlement'?'Only confirm after the payment reaches you. This will update the group’s balances.':'This pending repayment will not affect balances.',action==='confirm-settlement'?'confirmSettlement':'cancelSettlement',id);
  busy=true;el.disabled=true;
  try{
    if(action==='refresh'&&page==='admin'){await loadAdminReport();}
    else if(action==='refresh'){const main=$('#main-content');main.setAttribute('aria-busy','true');main.innerHTML='<div class=loading-skeleton role=status aria-label="Refreshing trip"><div></div><section></section><aside><i></i><i></i><i></i><i></i></aside></div>';try{data=await TripAPI.call('load');toast('You’re all caught up.');}finally{render();}}
    else if(action==='logout'){try{await TripAPI.logout();}finally{data=null;page='home';$('#modal').close();welcome();}}
    else if(action==='download')await downloadFile(id);
    else if(action==='toggle-checklist'){const d=data.documents.find(d=>d.id===id);await mutate('toggleChecklist',{id,version:d.version});render();if($('#modal').open)documentDetail(id);}
    else if(action==='confirmed'){const op=el.dataset.operation;if(op==='resetPreview')data=await TripAPI.resetPreview();else {const list=op.includes('Expense')?data.expenses:op.includes('Flight')?data.flights:op.includes('Document')?data.documents:data.settlements;const r=list.find(r=>r.id===id);await mutate(op,{id,version:r.version},el.dataset.requestId);}$('#modal').close();render();toast('All done.');}
  }finally{busy=false;el.disabled=false;}
}
document.addEventListener('click',event=>{const pageButton=event.target.closest('[data-page]');if(pageButton&&!busy){navigatePage(pageButton.dataset.page).catch(error=>toast(error.message,true));return;}const button=event.target.closest('[data-action]');if(button){event.preventDefault();act(button).catch(error=>formError(error.message));}});
document.addEventListener('input',event=>{if(event.target.closest('#modal form'))event.target.dataset.userEdited='true';if(event.target.id==='admin-search'){adminFilters.search=event.target.value;const position=event.target.selectionStart;render();$('#admin-search').focus();$('#admin-search').setSelectionRange(position,position);return;}if(event.target.closest('#expense-form'))updateSplitPreview();if(event.target.id==='expense-search'){filters.search=event.target.value;const focus=event.target.selectionStart;render();$('#expense-search').focus();$('#expense-search').setSelectionRange(focus,focus);}});
document.addEventListener('change',event=>{const el=event.target;if(el.closest('#modal form')&&el.type!=='file')el.dataset.userEdited='true';if(el.type==='file'&&['scanImage','receipt','file'].includes(el.name)&&el.files?.[0]?.type.startsWith('image/')){scanImageFile(el.files[0],el.form).catch(error=>formError(error.message));return;}if(el.name==='location'&&el.closest('#plan-form'))suggestHotelDates();if(el.id==='map-day-range'){mapDate=tripDates()[Number(el.value)-1]||mapDate;mapPlace='';render();requestAnimationFrame(()=>{alignMapDay();$('#map-day-range')?.focus({preventScroll:true});});return;}if(el.id==='itinerary-range'){const slides=[...tripDates(),ITINERARY_SUMMARY];itineraryDate=slides[Number(el.value)-1]||itineraryDate;render();requestAnimationFrame(()=>{alignSelectedDay();$('#itinerary-range')?.focus({preventScroll:true});});return;}if(el.name?.startsWith('admin-')){adminFilters[el.name.slice(6)]=el.value;render();return;}if(el.name==='currency'&&el.closest('#expense-form')){el.form.elements.rate.value=data.settings.rates[el.value]||'1';updateSplitPreview();}if(el.name==='kind')updateFileField();if(el.name?.startsWith('filter-')){filters[el.name.slice(7)]=el.value;render();}});
document.addEventListener('submit',async event=>{event.preventDefault();const form=event.target;if(busy||form.dataset.scanning)return;const submit=$('[type="submit"]',form);const oldText=submit.innerHTML;busy=true;submit.disabled=true;submit.innerHTML='<span class="spinner"></span> '+(form.id==='login-form'?'Signing in…':'Saving…');$('.form-error',form).hidden=true;
  try{
    const f=new FormData(form);let p=Object.fromEntries(f.entries());delete p.scanImage;const requestId=form.dataset.requestId;
    if(form.id==='login-form'){data=await TripAPI.login(selectedUser,p.code);page='home';}
    else if(form.id==='password-form'){await TripAPI.changePassword(data.me.id,p.currentPassword,p.newPassword,p.confirmation,requestId);form.reset();data=null;page='home';resetAdminReport();$('#modal').close();welcome();toast('Password changed. Sign in with your new password.');return;}
    else if(form.id==='expense-form'){
      const receipt=await readFile(f.get('receipt'));p=expensePayload(form);const result=await mutate('saveExpense',p,requestId);
      if(receipt){try{await mutate('saveDocument',{title:p.title+' — receipt',kind:'file',category:'Receipts',notes:'',url:'',date:p.date,checked:false,sharedWith:C.MEMBERS.map(u=>u.id),expenseId:result.savedId,flightId:'',file:receipt},requestId+'-receipt');}catch(error){toast('Expense saved. Receipt upload failed: '+error.message+' Attach it from expense details.',true);}}
    } else if(form.id==='flight-form'){p.passengers=f.getAll('passengers');p.sharedWith=f.getAll('sharedWith');if(form.dataset.id){p.id=form.dataset.id;p.version=Number(form.dataset.version);}await mutate('saveFlight',p,requestId);}
    else if(form.id==='document-form'){p.kind=form.elements.kind.value;p.sharedWith=f.getAll('sharedWith');p.expenseId=form.dataset.expenseId;p.flightId=form.dataset.flightId;const file=await readFile(f.get('file'));delete p.file;if(file)p.file=file;if(form.dataset.id){p.id=form.dataset.id;p.version=Number(form.dataset.version);p.checked=data.documents.find(d=>d.id===p.id).checked;}await mutate('saveDocument',p,requestId);}
    else if(form.id==='plan-form'){await savePlan(form,f,requestId);}
    else if(form.id==='settlement-form'){p.fromId=data.me.id;await mutate('recordSettlement',p,requestId);}
    else if(form.id==='received-settlement-form'){p.toId=data.me.id;await mutate('recordReceivedSettlement',p,requestId);}
    else if(form.id==='settings-form'){p.rates={INR:'1'};Object.keys(C.CURRENCIES).filter(c=>c!=='INR').forEach(c=>p.rates[c]=f.get('rate-'+c));p.version=Number(form.dataset.version);await mutate('saveSettings',p,requestId);}
    $('#modal').close();render();toast(form.id==='login-form'?'Welcome to the adventure.':'Saved. One less thing to think about.');
  }catch(error){formError(error.message);}finally{busy=false;submit.disabled=false;submit.innerHTML=oldText;}
});
$('#modal').addEventListener('cancel',event=>{if(busy)event.preventDefault();else cancelImageScan();});
try{document.documentElement.dataset.theme=localStorage.getItem('vietnam-theme-v2')==='dark'?'dark':'light';}catch{document.documentElement.dataset.theme='light';}
welcome();
// Establish the anonymous bridge while the visitor chooses an account.
if(location.protocol==='https:')TripAPI.prepareLogin();

window.addEventListener('resize',()=>{if(page==='itinerary')alignSelectedDay();if(page==='home')alignHomeDay();if(page==='map')alignMapDay();});

document.addEventListener('keydown',event=>{if(['Enter',' '].includes(event.key)&&event.target.matches('.map-pin')){event.preventDefault();event.target.dispatchEvent(new MouseEvent('click',{bubbles:true}));}});
